import { useState } from 'react';
import {
  JxCard,
  JxStepper,
  JxStep,
  JxInput,
  JxButton,
  JxStack,
  JxText,
  JxDivider,
} from '@jinx-ui/react';

type FormData = {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationFormProps = {
  onSubmit: (data: FormData) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const INITIAL_DATA: FormData = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [currentStep, setCurrentStep] = useState(0);
  const [formData, setFormData] = useState<FormData>(INITIAL_DATA);

  const isLastStep = currentStep === STEPS.length - 1;
  const isFirstStep = currentStep === 0;

  const updateField = (field: keyof FormData) => (value: string) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const handleNext = () => {
    if (!isLastStep) {
      setCurrentStep((step) => step + 1);
    }
  };

  const handleBack = () => {
    if (!isFirstStep) {
      setCurrentStep((step) => step - 1);
    }
  };

  const handleSubmit = () => {
    onSubmit(formData);
  };

  return (
    <JxCard className="jx-p-lg jx-max-w-md">
      <JxStack direction="column" gap="lg">
        <JxStepper activeStep={currentStep}>
          {STEPS.map((label) => (
            <JxStep key={label} label={label} />
          ))}
        </JxStepper>

        <JxDivider />

        {currentStep === 0 && (
          <JxStack direction="column" gap="md">
            <JxText variant="heading-sm">Контакты</JxText>
            <JxInput
              label="Полное имя"
              value={formData.fullName}
              onChange={updateField('fullName')}
              placeholder="Иван Иванов"
            />
            <JxInput
              label="Email"
              type="email"
              value={formData.email}
              onChange={updateField('email')}
              placeholder="ivan@example.com"
            />
            <JxInput
              label="Телефон"
              type="tel"
              value={formData.phone}
              onChange={updateField('phone')}
              placeholder="+7 900 000-00-00"
            />
          </JxStack>
        )}

        {currentStep === 1 && (
          <JxStack direction="column" gap="md">
            <JxText variant="heading-sm">Адрес</JxText>
            <JxInput
              label="Страна"
              value={formData.country}
              onChange={updateField('country')}
              placeholder="Россия"
            />
            <JxInput
              label="Город"
              value={formData.city}
              onChange={updateField('city')}
              placeholder="Москва"
            />
            <JxInput
              label="Улица и дом"
              value={formData.street}
              onChange={updateField('street')}
              placeholder="ул. Ленина, д. 1"
            />
            <JxInput
              label="Индекс"
              value={formData.zip}
              onChange={updateField('zip')}
              placeholder="123456"
            />
          </JxStack>
        )}

        {currentStep === 2 && (
          <JxStack direction="column" gap="md">
            <JxText variant="heading-sm">Проверка</JxText>
            <JxStack direction="column" gap="xs">
              <JxText variant="body-sm" style={{ color: 'var(--jx-color-text-secondary)' }}>
                Имя
              </JxText>
              <JxText variant="body-md">{formData.fullName || '—'}</JxText>
            </JxStack>
            <JxStack direction="column" gap="xs">
              <JxText variant="body-sm" style={{ color: 'var(--jx-color-text-secondary)' }}>
                Email
              </JxText>
              <JxText variant="body-md">{formData.email || '—'}</JxText>
            </JxStack>
            <JxStack direction="column" gap="xs">
              <JxText variant="body-sm" style={{ color: 'var(--jx-color-text-secondary)' }}>
                Телефон
              </JxText>
              <JxText variant="body-md">{formData.phone || '—'}</JxText>
            </JxStack>
            <JxStack direction="column" gap="xs">
              <JxText variant="body-sm" style={{ color: 'var(--jx-color-text-secondary)' }}>
                Адрес
              </JxText>
              <JxText variant="body-md">
                {[formData.street, formData.city, formData.country, formData.zip]
                  .filter(Boolean)
                  .join(', ') || '—'}
              </JxText>
            </JxStack>
          </JxStack>
        )}

        <JxDivider />

        <JxStack direction="row" justify="space-between">
          <JxButton variant="secondary" onClick={handleBack} disabled={isFirstStep}>
            Назад
          </JxButton>
          {isLastStep ? (
            <JxButton variant="primary" onClick={handleSubmit}>
              Отправить
            </JxButton>
          ) : (
            <JxButton variant="primary" onClick={handleNext}>
              Дальше
            </JxButton>
          )}
        </JxStack>
      </JxStack>
    </JxCard>
  );
}

